// themeOptions builds the theme <select> options, marking `current` selected.
// Keep this list in sync with layout.templ getThemeOptions — package demo
// imports examples (not the reverse), so the list can't be shared without an
// import cycle; it is duplicated here intentionally.
func themeOptions(current string) []selectfield.Option {
	pairs := []struct{ Key, Label string }{
		{"minimal", "Minimal"}, {"modern", "Modern"}, {"arctic", "Arctic"}, {"high-contrast", "High Contrast"},
		{"neo-brutalism", "Neo Brutalism"}, {"news", "News"}, {"industrial", "Industrial"}, {"90s", "90s"},
		{"pastel", "Pastel"}, {"christmas", "Christmas"}, {"halloween", "Halloween"}, {"zombie", "Halloween II"},
		{"prototype", "Prototype"}, {"totvs", "TOTVS"}, {"dracula", "Dracula"},
	}
	out := make([]selectfield.Option, 0, len(pairs))
	for _, p := range pairs {
		out = append(out, selectfield.Option{Value: p.Key, Label: p.Label, Selected: p.Key == current})
	}
	return out
}

